function showAccountDialog(){const dialog=$('#account-dialog');$('#account-error').textContent='';updateAccountMode();if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}
function closeAccountDialog(id){const dialog=$(id);if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');}
function paintAccount(){ $('#account-label').textContent=account?'已登录：'+account.username:'收藏可登录同步';$('#open-account').hidden=!!account;$('#logout-account').hidden=!account;$('#manage-email').hidden=!account;$('#manage-email').disabled=!emailEnabled;$('#manage-email').textContent=account?.email?'邮箱设置':'绑定邮箱';}
async function accountRequest(path,body){const response=await fetch(path,{method:body?'POST':'GET',cache:'no-store',...(body?{headers:{'content-type':'application/json'},body:JSON.stringify(body)}:{})});const result=await response.json();if(!response.ok)throw Error(result.error||'账户操作失败');return result;}
async function adoptAccount(result,mergeGuest=true,epoch=accountEpoch){
 if(epoch!==accountEpoch)return;if(typeof result.emailEnabled==='boolean')emailEnabled=result.emailEnabled;if(Object.hasOwn(result,'emailProvider'))emailProvider=result.emailProvider;account=result.user;
 if(!account){saved=localSaved.slice();disliked=localDisliked.slice();watchState={...localWatchState};paintAccount();updateAccountMode();render();return;}
 let cloudDislikes=result.dislikes||[];disliked=[...new Set([...cloudDislikes,...(mergeGuest?localDisliked:[])])];
 let cloud=result.favorites||[],cloudWatch=result.watchlist||{};saved=[...new Set([...cloud,...(mergeGuest?localSaved:[])])];watchState={...(mergeGuest?localWatchState:{}),...cloudWatch};paintAccount();updateAccountMode();render();
 if(mergeGuest&&(localSaved.length||localDisliked.length||Object.keys(localWatchState).length)){try{const incoming=localSaved.slice();for(let i=0;i<incoming.length;i+=100){const update=await accountRequest('/api/account/favorites',{add:incoming.slice(i,i+100),remove:[]});if(epoch!==accountEpoch)return;cloud=update.favorites;}localSaved=[];try{localStorage.setItem('drama-favs','[]');}catch{}
 for(const status of ['watched','want']){const ids=Object.keys(localWatchState).filter(id=>localWatchState[id]===status);for(let i=0;i<ids.length;i+=100){const update=await accountRequest('/api/account/watchlist',{ids:ids.slice(i,i+100),status,merge:true});if(epoch!==accountEpoch)return;cloudWatch=update.watchlist;}}
 for(let i=0;i<localDisliked.length;i+=100){const update=await accountRequest('/api/account/dislikes',{add:localDisliked.slice(i,i+100),remove:[]});if(epoch!==accountEpoch)return;cloudDislikes=update.dislikes;}localDisliked=[];disliked=cloudDislikes;try{localStorage.setItem('drama-dislikes','[]');}catch{}
 localWatchState={};try{localStorage.setItem('drama-watchlist','{}');}catch{}saved=cloud;watchState=cloudWatch;render();}catch{$('#account-sync-status').textContent='已登录，部分本地清单暂未同步成功，稍后刷新会重试；本地记录仍保留';return;}}
 $('#account-sync-status').textContent='收藏与观看清单已同步到账号';
}

async function loadAccount(){const epoch=accountEpoch;try{const result=await accountRequest('/api/account');if(epoch!==accountEpoch)return;await adoptAccount(result,localSaved.length>0||localDisliked.length>0||Object.keys(localWatchState).length>0);}catch{$('#account-sync-status').textContent=account?'暂时无法同步收藏，请稍后重试':'暂时无法连接账号，可继续本地收藏';}}
function updateAccountMode(){const mode=$('#account-mode').value||'login',register=mode==='register',reset=mode==='email-reset',withEmail=register&&$('#register-with-email').checked&&emailEnabled,firebase=emailProvider==='firebase';$('#account-password').autocomplete=mode==='login'?'current-password':'new-password';$('#account-password-label').textContent=mode==='recover'||reset?'新密码':'密码';$('#account-password-wrap').hidden=firebase&&reset;$('#account-password').required=!(firebase&&reset);$('#account-password').disabled=firebase&&reset;$('#recovery-input-wrap').hidden=mode!=='recover';$('#account-recovery-input').required=mode==='recover';$('#account-username-wrap').hidden=reset;$('#account-username').required=!reset;$('#account-username').disabled=reset;$('#register-email-option').hidden=!register;$('#register-with-email').disabled=!emailEnabled;$('#email-unavailable-note').hidden=emailEnabled;$('#email-reset-option').disabled=!emailEnabled;$('#account-email-wrap').hidden=!(withEmail||reset);$('#account-email').required=withEmail||reset;$('#account-email-code').required=(withEmail||reset)&&!firebase;$('#account-email-code').disabled=firebase;$('#email-code-label').hidden=firebase;$('#send-account-email').textContent=firebase?(reset?'发送找回邮件':'发送验证邮件'):'发送验证码';$('#no-email-warning').hidden=!register||withEmail;$('#no-email-ack').required=register&&!withEmail;$('#account-submit').textContent=firebase&&reset?'发送找回密码邮件':register?(firebase&&withEmail&&authEmailChallenge?.firebasePending?'已验证，注册并登录':'注册并登录'):mode==='recover'||reset?'重设密码并登录':'登录';}

function maybeGuestLibraryPrompt(){if(guestFavoritePromptShown)return;guestFavoritePromptShown=true;const dialog=$('#favorite-login-dialog');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}
function toggleWatchStatus(group,requested,button){if(!group)return Promise.resolve();const epoch=accountEpoch;if(button)button.disabled=true;const execute=async()=>{if(epoch!==accountEpoch)return;const ids=group.members.map(m=>m.id),status=groupWatchStatus(group)===requested?null:requested;try{if(account){let result;for(let i=0;i<ids.length;i+=100){result=await accountRequest('/api/account/watchlist',{ids:ids.slice(i,i+100),status});if(epoch!==accountEpoch||result.user?.id!==account?.id)return;}watchState=result.watchlist;$('#account-sync-status').textContent=status==='watched'?'已标记已看并同步':status==='want'?'已加入想看并同步':'已取消观看标记';}else{for(const id of ids){if(status)watchState[id]=status;else delete watchState[id];}localWatchState={...watchState};try{localStorage.setItem('drama-watchlist',JSON.stringify(localWatchState));}catch{}if(status)maybeGuestLibraryPrompt();}render();}catch(error){$('#account-sync-status').textContent=error.message;if(button)button.disabled=false;}};const task=watchSaveQueue.then(execute,execute);watchSaveQueue=task.catch(()=>{});return task;}
async function toggleDislike(group,button){const epoch=accountEpoch;const ids=group.members.map(m=>m.id),remove=ids.some(id=>disliked.includes(id));if(button)button.disabled=true;try{if(account){const result=await accountRequest('/api/account/dislikes',{add:remove?[]:ids,remove:remove?ids:[]});if(epoch!==accountEpoch||result.user?.id!==account?.id)return;disliked=result.dislikes;$('#account-sync-status').textContent=remove?'已取消狠踩':'已狠踩并同步到账号';}else{disliked=remove?disliked.filter(id=>!ids.includes(id)):[...new Set([...disliked,...ids])];localDisliked=disliked.slice();try{localStorage.setItem('drama-dislikes',JSON.stringify(localDisliked));}catch{}if(!remove)maybeGuestLibraryPrompt();}render();}catch(error){$('#account-sync-status').textContent=error.message;if(button)button.disabled=false;}}
async function toggleFavorite(group,button){const epoch=accountEpoch;const ids=group.members.map(m=>m.id),remove=ids.some(id=>saved.includes(id));if(button)button.disabled=true;try{if(account){const result=await accountRequest('/api/account/favorites',{add:remove?[]:ids,remove:remove?ids:[]});if(epoch!==accountEpoch||result.user?.id!==account?.id)return;saved=result.favorites;$('#account-sync-status').textContent=remove?'已从账号收藏中移除':'已收藏并同步到账号';}else{saved=remove?saved.filter(id=>!ids.includes(id)):[...new Set([...saved,...ids])];localSaved=saved.slice();try{localStorage.setItem('drama-favs',JSON.stringify(localSaved));}catch{}if(!remove)maybeGuestLibraryPrompt();}render();}catch(error){$('#account-sync-status').textContent=error.message;if(button)button.disabled=false;}}
$('#open-account').onclick=showAccountDialog;$('#account-close').onclick=()=>closeAccountDialog('#account-dialog');$('#account-mode').onchange=()=>{authEmailChallenge=null;$('#account-email-code').value='';updateAccountMode();};
function dismissFavoritePrompt(){if($('#favorite-no-remind').checked){try{localStorage.setItem('drama-no-login-prompt','true')}catch{}}closeAccountDialog('#favorite-login-dialog');}
$('#favorite-no-remind').onchange=()=>{try{localStorage.setItem('drama-no-login-prompt',String($('#favorite-no-remind').checked))}catch{}};
$('#favorite-continue').onclick=dismissFavoritePrompt;$('#favorite-login').onclick=()=>{dismissFavoritePrompt();showAccountDialog();};
$('#account-form').onsubmit=async event=>{event.preventDefault();const button=$('#account-submit');button.disabled=true;$('#account-error').textContent='正在处理…';try{const mode=$('#account-mode').value||'login',epoch=++accountEpoch,withEmail=mode==='register'&&$('#register-with-email').checked&&emailEnabled;let result;if(emailProvider==='firebase'&&mode==='email-reset'){result=await accountRequest('/api/account/firebase/reset-email',{email:$('#account-email').value});$('#account-error').textContent=result.message;return;}if(emailProvider==='firebase'&&withEmail){if(!authEmailChallenge?.firebasePending){result=await accountRequest('/api/account/firebase/register',{username:$('#account-username').value,password:$('#account-password').value,email:$('#account-email').value});authEmailChallenge={firebasePending:true};$('#account-error').textContent=result.message;updateAccountMode();return;}result=await accountRequest('/api/account/login',{username:$('#account-email').value,password:$('#account-password').value});}else{const emailDetails=mode==='email-reset'||withEmail?{email:$('#account-email').value,code:$('#account-email-code').value,challengeId:authEmailChallenge?.id}:{};result=await accountRequest(mode==='email-reset'?'/api/account/email/reset':'/api/account/'+mode,{...emailDetails,username:$('#account-username').value,password:$('#account-password').value,...(mode==='recover'?{recoveryCode:$('#account-recovery-input').value}:{})});}if(epoch!==accountEpoch)return;await adoptAccount(result,true);$('#account-password').value='';$('#account-recovery-input').value='';$('#account-email-code').value='';authEmailChallenge=null;closeAccountDialog('#account-dialog');if(result.recoveryCode){$('#recovery-hint').textContent=result.user?.email?'已绑定邮箱，可通过邮件找回密码。恢复码也可作为备份，只显示这一次。':'忘记密码时，使用用户名和此恢复码重设密码。恢复码只显示这一次，请妥善保存。';$('#recovery-code').value=result.recoveryCode;const dialog=$('#recovery-dialog');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}}catch(error){$('#account-error').textContent=error.message;}finally{button.disabled=false;}};

$('#logout-account').onclick=async()=>{try{++accountEpoch;await accountRequest('/api/account/logout',{});account=null;saved=localSaved.slice();disliked=localDisliked.slice();watchState={...localWatchState};paintAccount();render();$('#account-sync-status').textContent='已退出，账号收藏仍保存在云端';}catch(error){$('#account-sync-status').textContent=error.message;}};
$('#recovery-dialog').addEventListener('close',()=>{$('#recovery-code').value='';});$('#recovery-close').onclick=()=>closeAccountDialog('#recovery-dialog');$('#copy-recovery').onclick=async()=>{try{await navigator.clipboard.writeText($('#recovery-code').value);$('#recovery-status').textContent='已复制，请妥善保存';}catch{$('#recovery-status').textContent='请长按恢复码复制并保存';}};
$('#register-with-email').onchange=updateAccountMode;
$('#account-email').oninput=()=>{authEmailChallenge=null;$('#account-email-code').value='';};
$('#send-account-email').onclick=async()=>{const button=$('#send-account-email');button.disabled=true;try{const email=$('#account-email').value,purpose=$('#account-mode').value==='email-reset'?'reset':'register';const result=emailProvider==='firebase'?await accountRequest('/api/account/firebase/'+(purpose==='reset'?'reset-email':'register'),{email,username:$('#account-username').value,password:$('#account-password').value}):await accountRequest('/api/account/email/send',{email,purpose});authEmailChallenge=emailProvider==='firebase'?{firebasePending:purpose==='register'}:{id:result.challengeId,email};$('#email-send-status').textContent=result.message;updateAccountMode();}catch(error){$('#email-send-status').textContent=error.message;}finally{button.disabled=false;}};

$('#manage-email').onclick=()=>{$('#bind-email-address').value=account?.email||'';$('#bound-email-label').textContent=account?.email?'当前已绑定：'+account.email:'验证后可使用邮箱登录和找回密码';$('#bind-email-status').textContent='';$('#bind-email-code-label').hidden=emailProvider==='firebase';$('#bind-email-code').required=emailProvider!=='firebase';$('#bind-email-code').disabled=emailProvider==='firebase';$('#send-bind-email').textContent=emailProvider==='firebase'?'发送验证邮件':'发送验证码';$('#confirm-bind-email').textContent=emailProvider==='firebase'?'已验证，完成绑定':'验证并绑定';bindEmailChallenge=null;const dialog=$('#bind-email-dialog');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');};
$('#bind-email-close').onclick=()=>closeAccountDialog('#bind-email-dialog');$('#bind-email-dialog').addEventListener('close',()=>{$('#bind-email-password').value='';$('#bind-email-code').value='';});
$('#send-bind-email').onclick=async()=>{const button=$('#send-bind-email');button.disabled=true;try{const result=await accountRequest(emailProvider==='firebase'?'/api/account/firebase/bind':'/api/account/email/send',{purpose:'bind',email:$('#bind-email-address').value,password:$('#bind-email-password').value});if(result.user){await adoptAccount(result,false);closeAccountDialog('#bind-email-dialog');$('#account-sync-status').textContent='邮箱已绑定';return;}bindEmailChallenge=result.challengeId;$('#bind-email-status').textContent=result.message;}catch(error){$('#bind-email-status').textContent=error.message;}finally{button.disabled=false;}};

$('#bind-email-address').oninput=()=>{bindEmailChallenge=null;$('#bind-email-code').value='';};
$('#bind-email-form').onsubmit=async event=>{event.preventDefault();const button=$('#confirm-bind-email');button.disabled=true;try{const result=await accountRequest(emailProvider==='firebase'?'/api/account/firebase/bind':'/api/account/email/bind',{password:$('#bind-email-password').value,email:$('#bind-email-address').value,code:$('#bind-email-code').value,challengeId:bindEmailChallenge});if(result.verificationPending){$('#bind-email-status').textContent=result.message;return;}await adoptAccount(result,false);$('#account-sync-status').textContent='邮箱已绑定，可以用邮箱登录和找回密码';closeAccountDialog('#bind-email-dialog');}catch(error){$('#bind-email-status').textContent=error.message;}finally{button.disabled=false;}};
loadAccount();

let firebaseActionState=null;
$('#firebase-action-form').onsubmit=async event=>{event.preventDefault();if(!firebaseActionState)return;const button=$('#firebase-action-submit');button.disabled=true;try{const result=await accountRequest('/api/account/firebase/action',{...firebaseActionState,...(firebaseActionState.mode==='resetPassword'?{password:$('#firebase-new-password').value}:{})});if(firebaseActionState.mode==='resetPassword'){++accountEpoch;account=null;saved=localSaved.slice();disliked=localDisliked.slice();watchState={...localWatchState};paintAccount();render();}$('#firebase-action-message').textContent=result.message;$('#firebase-action-form').hidden=true;$('#firebase-new-password').value='';firebaseActionState=null;$('#firebase-action-close').textContent='返回登录';if(typeof history!=='undefined')history.replaceState(null,'','/');}catch(error){$('#firebase-action-message').textContent=error.message;}finally{button.disabled=false;}};
$('#firebase-action-close').onclick=()=>{firebaseActionState=null;$('#firebase-new-password').value='';closeAccountDialog('#firebase-action-dialog');if(typeof history!=='undefined')history.replaceState(null,'','/');$('#account-mode').value='login';showAccountDialog();};
if(typeof location!=='undefined'){const action=new URLSearchParams(location.search),mode=action.get('mode'),oobCode=action.get('oobCode');if(['verifyEmail','resetPassword'].includes(mode)&&oobCode){firebaseActionState={mode,oobCode};$('#firebase-action-title').textContent=mode==='verifyEmail'?'验证邮箱':'重设密码';$('#firebase-action-message').textContent=mode==='verifyEmail'?'请点击下方按钮完成邮箱验证，之后返回原页面登录或完成绑定。':'请输入至少 8 位的新密码。';$('#firebase-reset-wrap').hidden=mode!=='resetPassword';$('#firebase-new-password').required=mode==='resetPassword';$('#firebase-action-submit').textContent=mode==='verifyEmail'?'验证邮箱':'保存新密码';const dialog=$('#firebase-action-dialog');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}}
